function parseDate(v){if(!v)return null;const [y,m,d]=String(v).split('-').map(Number);return y&&m&&d?new Date(y,m-1,d):null}
function dateKey(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function weekend(d){return [0,6].includes(d.getDay())}
function datesBetween(a,b,showWeekends){const s=parseDate(a),e=parseDate(b);if(!s||!e||s>e)return[];const out=[];for(const d=new Date(s);d<=e;d.setDate(d.getDate()+1)){if(showWeekends||!weekend(d))out.push({key:dateKey(d),date:new Date(d)})}return out}
function addWorkingDays(v,n){const d=parseDate(v);if(!d)return'';let r=Math.max(0,Number(n||0));while(r){d.setDate(d.getDate()+1);if(!weekend(d))r--}return dateKey(d)}
function fmt(v,short=false){if(!v)return'—';const d=parseDate(v);if(!d)return v;return d.toLocaleDateString('en-US',short?{month:'short',day:'2-digit'}:{month:'short',day:'2-digit',year:'numeric'})}
function initials(v){return String(v||'').trim().split(/\s+/).slice(0,2).map(x=>x[0]?.toUpperCase()||'').join('')}
function contrast(hex){const h=String(hex||'#64748b').replace('#','').padEnd(6,'0').slice(0,6),r=parseInt(h.slice(0,2),16)||0,g=parseInt(h.slice(2,4),16)||0,b=parseInt(h.slice(4,6),16)||0;return (r*299+g*587+b*114)/1000>=145?'#0f172a':'#fff'}
function buildLocations(rows){const map=new Map(rows.map(x=>[x.id,x]));function path(x){const p=[],seen=new Set();let c=x;while(c&&!seen.has(c.id)){seen.add(c.id);if(c.name)p.unshift(c.name);c=c.parent_id?map.get(c.parent_id):null}return p.join(' / ')}return rows.map(x=>({...x,path:path(x)})).sort((a,b)=>(Number(a.sequence_number||9999)-Number(b.sequence_number||9999))||a.path.localeCompare(b.path))}

