 const[items,setItems]=useState([]),[activities,setActivities]=useState([]),[handoffs,setHandoffs]=useState([]),[participants,setParticipants]=useState([]),[sessionLocations,setSessionLocations]=useState([]),[needs,setNeeds]=useState([]),[summary,setSummary]=useState(null)
 const[selectedItemId,setSelectedItemId]=useState(null),[selectedNeedId,setSelectedNeedId]=useState(null),[dependencyView,setDependencyView]=useState('selected'),[showWeekends,setShowWeekends]=useState(false),[zoom,setZoom]=useState(1)
