 const timeline=useMemo(()=>datesBetween(start,end,showWeekends),[start,end,showWeekends]), indexMap=useMemo(()=>new Map(timeline.map((x,i)=>[x.key,i])),[timeline]), day=DAY*zoom, timeWidth=Math.max(1,timeline.length)*day, boardWidth=LABEL+timeWidth+TARGET
 const laneLayout=useMemo(()=>{const tracksByItem=new Map(),rows=[];let top=HEADER;for(const lane of activeLanes){const candidates=items.map(item=>{const a=activityMap.get(item.production_activity_id);if(!a||a.location_id!==lane.location_id)return null;const si=indexMap.get(item.planned_start_date),fi=indexMap.get(item.planned_finish_date);if(si===undefined||fi===undefined)return null;return{item,si,fi}}).filter(Boolean).sort((a,b)=>a.si-b.si||a.fi-b.fi);const ends=[];for(const c of candidates){let track=ends.findIndex(end=>c.si>end);if(track<0){track=ends.length;ends.push(c.fi)}else ends[track]=c.fi;tracksByItem.set(c.item.id,track)}const trackCount=Math.max(1,ends.length),height=Math.max(LANE,26+trackCount*104+18);rows.push({lane,top,height,trackCount});top+=height}return{rows,tracksByItem,totalHeight:Math.max(HEADER+LANE,top)}},[activeLanes,items,activityMap,indexMap])
