 async function createSession(e){e.preventDefault();if(!project||saving)return;const f=sessionForm;if(!f.name.trim()||!f.phase.trim()||!f.milestone.trim()||!f.target){setError('Session name, phase, target milestone and target date are required.');return}setSaving(true);try{const uid=await currentUser();const{data:s,error:se}=await supabase.from('pull_planning_sessions').insert({organization_id:project.organization_id,project_id:project.id,name:f.name.trim(),phase_name:f.phase.trim(),scope_description:f.scope.trim()||null,facilitator_name:f.facilitator.trim()||null,session_date:f.date||null,planning_horizon_start:f.start||null,planning_horizon_end:f.end||null,status:'draft',created_by:uid}).select().single();if(se)throw se;const{data:m,error:me}=await supabase.from('pull_planning_milestones').insert({organization_id:project.organization_id,project_id:project.id,pull_planning_session_id:s.id,name:f.milestone.trim(),target_condition:f.condition.trim()||null,target_date:f.target,source_type:'pull_planning',is_primary:true,sequence_number:1}).select().single();if(me){await supabase.from('pull_planning_sessions').delete().eq('id',s.id);throw me}setSessions(x=>[s,...x]);setMilestones(x=>({...x,[s.id]:[m]}));setSessionId(s.id);setModal(null);window.history.replaceState({},'',`/dashboard/projects/pullplanning?projectId=${projectId}&sessionId=${s.id}`)}catch(e){setError(e.message)}finally{setSaving(false)}}
